#!/usr/bin/env python3
"""NOVA 13 visual layer: command-center UI for AWG management."""

NEW_THEME = r'''<style>
:root{--n-bg:#06080d;--n-panel:#0b1018;--n-panel2:#0f1621;--n-line:rgba(255,255,255,.075);--n-text:#f4f7fb;--n-muted:#8390a3;--n-blue:#6f8cff;--n-cyan:#46dfc2;--n-red:#ff6f87;--n-yellow:#f2c75c}
html,body{background:var(--n-bg)!important;color:var(--n-text)!important;overflow-y:scroll!important;scrollbar-color:#58667d #080c13!important;scrollbar-width:auto!important}
body{overflow-x:hidden!important}
body::-webkit-scrollbar,.sidebar::-webkit-scrollbar,.table-wrap::-webkit-scrollbar,.code::-webkit-scrollbar{width:12px!important;height:12px!important;display:block!important}
body::-webkit-scrollbar-track,.sidebar::-webkit-scrollbar-track,.table-wrap::-webkit-scrollbar-track,.code::-webkit-scrollbar-track{background:#080c13!important}
body::-webkit-scrollbar-thumb,.sidebar::-webkit-scrollbar-thumb,.table-wrap::-webkit-scrollbar-thumb,.code::-webkit-scrollbar-thumb{background:#58667d!important;border:3px solid #080c13!important;border-radius:10px!important}
body::-webkit-scrollbar-thumb:hover{background:#71819d!important}
body:before{background:radial-gradient(850px 500px at 8% -10%,rgba(76,106,255,.17),transparent 62%),radial-gradient(800px 500px at 105% 100%,rgba(38,211,177,.10),transparent 60%),linear-gradient(180deg,#06080df5,#06080bfc),url('/background.svg?v=NOVA13')!important}
body:after{background-image:linear-gradient(rgba(255,255,255,.022) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.022) 1px,transparent 1px)!important;background-size:52px 52px!important;opacity:.5!important}
.app{min-height:100vh}
.sidebar{width:272px!important;padding:16px 12px!important;background:rgba(6,9,15,.88)!important;border-right:1px solid var(--n-line)!important;box-shadow:22px 0 70px rgba(0,0,0,.30)!important}
.brand{padding:7px 9px 25px!important}.logo{width:46px!important;height:46px!important;border-radius:15px!important;background:linear-gradient(135deg,#7b92ff,#42d8bd)!important;box-shadow:0 12px 38px rgba(80,111,255,.26)!important}.brand b{font-size:20px!important;letter-spacing:-.04em!important}.brand b span{color:var(--n-cyan)!important}.brand small{font-size:8px!important;letter-spacing:.20em!important;color:#647188!important}
.section{margin:19px 9px 7px!important;color:#4e5c70!important;font-size:9px!important}.nav{gap:3px!important}.nav a{min-height:42px!important;padding:10px 12px!important;border-radius:12px!important;color:#98a6b9!important}.nav a i{font-size:16px!important;width:21px!important}.nav a:hover{background:rgba(255,255,255,.045)!important;color:#fff!important;transform:translateX(2px)!important}.nav a.active{background:linear-gradient(100deg,rgba(111,140,255,.19),rgba(70,223,194,.055))!important;border-color:rgba(111,140,255,.22)!important;box-shadow:inset 3px 0 var(--n-blue),0 7px 22px rgba(0,0,0,.12)!important;color:#fff!important}.keenetic-nav{background:linear-gradient(100deg,rgba(62,141,184,.22),rgba(54,210,184,.10))!important;border-color:rgba(76,203,195,.27)!important;color:#c9f8ee!important}
.server{margin:20px 2px 0!important;padding:13px!important;border-radius:14px!important;background:rgba(255,255,255,.035)!important;border-color:var(--n-line)!important}
.main{width:calc(100% - 272px)!important;margin-left:272px!important;padding:0 44px 64px!important}.topbar{height:72px!important;margin:0 -44px 30px!important;padding:0 44px!important;background:rgba(6,9,14,.76)!important;border-bottom:1px solid var(--n-line)!important}.topbar .title{font-size:13px!important;color:#cbd4e0!important}.wrap{max-width:1600px!important}
.hero{margin:8px 0 25px!important}.eyebrow{color:#8198ff!important;font-size:9px!important;letter-spacing:.22em!important}.hero h1{font-size:44px!important;line-height:1.02!important;letter-spacing:-.065em!important;margin:8px 0!important}.hero p{font-size:13px!important;color:#7e8ca0!important}
.card{background:linear-gradient(145deg,rgba(17,24,35,.90),rgba(8,12,18,.94))!important;border:1px solid var(--n-line)!important;border-radius:18px!important;box-shadow:0 22px 70px rgba(0,0,0,.28)!important}.grid4{gap:14px!important}.metric{min-height:140px!important;padding:20px!important}.metric .label{color:#718097!important}.metric .value{font-size:33px!important;letter-spacing:-.05em!important}.metric .sub{color:#647389!important}
.dashboard-grid{gap:14px!important;margin-top:14px!important}.dashboard-grid>.card{min-width:0}.actions{gap:9px!important}.action{padding:16px!important;border-radius:14px!important;background:rgba(255,255,255,.022)!important}.action:hover{transform:translateY(-2px)!important;border-color:rgba(111,140,255,.30)!important;background:rgba(111,140,255,.045)!important}.action b{font-size:13px!important}
.toolbar{min-height:38px!important}.toolbar h2{font-size:17px!important}.btn,button{min-height:38px!important;border-radius:10px!important;background:linear-gradient(135deg,#718aff,#526ee5)!important;box-shadow:0 8px 24px rgba(70,91,210,.18)!important}.btn.secondary{background:rgba(255,255,255,.04)!important;border:1px solid var(--n-line)!important;box-shadow:none!important}.btn.danger{background:#35131f!important;border:1px solid #632d3d!important;color:#ff9bab!important}
input,select,.input{min-height:42px!important;background:#070b12!important;border:1px solid rgba(255,255,255,.10)!important;border-radius:10px!important;color:#f5f7fb!important}input:focus,select:focus{border-color:#718aff!important;box-shadow:0 0 0 3px rgba(113,138,255,.11)!important}label{color:#a9b4c4!important}
.table-wrap{border-radius:12px!important}table{min-width:740px!important}th{padding:14px 9px!important;color:#64738a!important;border-bottom-color:rgba(255,255,255,.09)!important}td{padding:14px 9px!important;border-bottom-color:rgba(255,255,255,.055)!important}.badge{padding:6px 9px!important}.notice{border-radius:12px!important}.kv{border-radius:12px!important}.kv div{background:rgba(12,18,27,.88)!important}.code{border-radius:12px!important}
.nova-float{right:26px!important;bottom:25px!important;border-radius:12px!important;background:linear-gradient(135deg,rgba(28,61,88,.97),rgba(12,65,55,.97))!important;border-color:rgba(73,216,197,.35)!important;box-shadow:0 16px 45px rgba(0,0,0,.40)!important}
.login-shell{background:radial-gradient(650px 440px at 50% 38%,rgba(87,111,255,.13),transparent 66%)!important}.login-card{width:min(470px,100%)!important;padding:34px!important;border-radius:22px!important;background:rgba(10,15,23,.86)!important;border:1px solid rgba(255,255,255,.10)!important;box-shadow:0 40px 120px rgba(0,0,0,.58)!important}
.footer{color:#536176!important}
@media(max-width:1050px){.sidebar{width:245px!important}.main{width:calc(100% - 245px)!important;margin-left:245px!important;padding-left:25px!important;padding-right:25px!important}.topbar{margin-left:-25px!important;margin-right:-25px!important;padding-left:25px!important;padding-right:25px!important}}
@media(max-width:760px){.sidebar{width:278px!important}.main{width:100%!important;margin-left:0!important;padding:0 15px 40px!important}.topbar{margin:0 -15px 18px!important;padding:0 15px!important;height:64px!important}.hero h1{font-size:32px!important}.nova-float{right:14px!important;bottom:14px!important}.nova-float span{display:none!important}}
</style>'''

def apply(nova):
    nova.NOVA_CSS += NEW_THEME
    nova.core.BG_VERSION='NOVA13'
    return nova
